/**
 * salary-detail.ts — typed access to the committed official-data files that
 * enrich the /salary pages beyond comp_benchmarks' p25/p50/p75:
 *
 *   oews-detail.json        BLS OEWS full distribution + employment + LQ
 *   state-projections.json  Projections Central state long-term projections
 *
 * Both are generated by scripts/fetch-salary-data.mjs (never hand-edited).
 * Also holds the national BLS Occupational Outlook Handbook figures, which
 * were read live from bls.gov/ooh (pages last modified August 27, 2026).
 */
import oews from "./oews-detail.json";
import projections from "./state-projections.json";

export type Pctl = { p10: number | null; p25: number | null; p50: number | null; p75: number | null; p90: number | null };

export type OewsDetail = {
  emp: number | null;
  hourly: Pctl;
  annual: Pctl;
  hourlyMean: number | null;
  annualMean: number | null;
  /** Jobs in this occupation per 1,000 jobs in the area (not published nationally). */
  per1000: number | null;
  /** Location quotient: area share of jobs vs the U.S. share (1.0 = same). */
  lq: number | null;
  /** Fields BLS top-codes (at or above $115.00/hr or $239,200/yr). */
  topCoded: ReadonlySet<string>;
};

type Raw = number | string | null;
type OewsFile = {
  vintage: string;
  fields: string[];
  socs: Record<string, { national: Raw[] | null; states: Record<string, Raw[]>; metros: Record<string, Raw[]> }>;
};
const OEWS = oews as unknown as OewsFile;

export const OEWS_VINTAGE: string = OEWS.vintage;

function unpack(arr: Raw[] | null | undefined): OewsDetail | null {
  if (!arr) return null;
  const v: Record<string, number | null> = {};
  const topCoded = new Set<string>();
  OEWS.fields.forEach((f, i) => {
    const x = arr[i];
    if (x === "#") {
      topCoded.add(f);
      v[f] = null;
    } else v[f] = typeof x === "number" ? x : null;
  });
  const p = (prefix: "h" | "a"): Pctl => ({
    p10: v[`${prefix}10`], p25: v[`${prefix}25`], p50: v[`${prefix}50`], p75: v[`${prefix}75`], p90: v[`${prefix}90`],
  });
  return {
    emp: v.emp, hourly: p("h"), annual: p("a"), hourlyMean: v.hMean, annualMean: v.aMean,
    per1000: v.per1000, lq: v.lq, topCoded,
  };
}

export function nationalDetail(soc: string): OewsDetail | null {
  return unpack(OEWS.socs[soc]?.national);
}
export function stateDetail(soc: string, stateCode: string): OewsDetail | null {
  return unpack(OEWS.socs[soc]?.states[stateCode]);
}
/** Metro/nonmetro detail by OEWS area code (comp_benchmarks strips leading zeros). */
export function metroDetail(soc: string, areaCode: string): OewsDetail | null {
  const row = OEWS.socs[soc]?.metros[areaCode.padStart(7, "0")];
  return row ? unpack(row.slice(1)) : null;
}

export type MetroDetailRow = OewsDetail & { code: string; name: string };

/** Every metro (not nonmetro) area for a SOC whose name carries this state code. */
export function stateMetroDetails(soc: string, stateCode: string): MetroDetailRow[] {
  const metros = OEWS.socs[soc]?.metros ?? {};
  const out: MetroDetailRow[] = [];
  for (const [code, row] of Object.entries(metros)) {
    const name = String(row[0]);
    const i = name.lastIndexOf(",");
    if (i < 0) continue;
    const codes = name.slice(i + 1).trim().split(/[-\s]+/);
    if (!codes.includes(stateCode)) continue;
    const d = unpack(row.slice(1));
    if (d) out.push({ ...d, code, name });
  }
  return out;
}

export type Projection = {
  base: number | null;
  projected: number | null;
  change: number | null;
  pct: number | null;
  openings: number | null;
  lmiUrl: string | null;
};
type ProjFile = { period: string; socs: Record<string, Record<string, Projection>> };
const PROJ = projections as unknown as ProjFile;

/** e.g. "2024–2034" (en dash: numeric range). */
export const PROJECTION_PERIOD: string = PROJ.period.replace("-", "–");

export function stateProjection(soc: string, stateCode: string): Projection | null {
  return PROJ.socs[soc]?.[stateCode] ?? null;
}
export function nationalProjection(soc: string): Projection | null {
  return PROJ.socs[soc]?.US ?? null;
}

/**
 * BLS Occupational Outlook Handbook, national outlook (read live 2026-10-19;
 * pages last modified August 27, 2026). The OOH "Dentists" page covers ALL
 * dentists (general + specialists), so label it that way when shown.
 */
export type OohOutlook = {
  title: string;
  url: string;
  period: string;
  jobs: number;
  jobsYear: string;
  pct: number;
  descriptor: string;
  change: number;
  openings: number;
};

export const OOH_OUTLOOK: Readonly<Record<string, OohOutlook>> = {
  "29-1292": { title: "Dental Hygienists", url: "https://www.bls.gov/ooh/healthcare/dental-hygienists.htm", period: "2025–35", jobs: 225300, jobsYear: "2025", pct: 8, descriptor: "much faster than the average for all occupations", change: 17900, openings: 15000 },
  "31-9091": { title: "Dental Assistants", url: "https://www.bls.gov/ooh/healthcare/dental-assistants.htm", period: "2025–35", jobs: 388600, jobsYear: "2025", pct: 7, descriptor: "much faster than the average for all occupations", change: 28800, openings: 53000 },
  "29-1021": { title: "Dentists (all dentists, including specialists)", url: "https://www.bls.gov/ooh/healthcare/dentists.htm", period: "2025–35", jobs: 161400, jobsYear: "2025", pct: 6, descriptor: "faster than the average for all occupations", change: 9000, openings: 4800 },
};
export const OOH_LAST_MODIFIED = "August 27, 2026";

/** BLS occupation profile page for a SOC (May vintage; lists state + metro tables). */
export function oewsProfileUrl(soc: string): string {
  return `https://www.bls.gov/oes/current/oes${soc.replace("-", "")}.htm`;
}
